public static boolean enabled(TFMPageID _page, Name _AIName, int _AI)
{
    TFMGS1AITypeBarcodeSetup    typeBarcodeValue;
    TFMGS1AISetup               setup;

    select firstonly RecId from setup where setup.Name == _AIName && setup.GS1AI == _AI;
    if (!setup.RecId)
    {
        return false;
    }
    select firstonly typeBarcodeValue where typeBarcodeValue.PageID == _page && typeBarcodeValue.TFMGS1AITableRef == setup.RecId;
    return typeBarcodeValue.Enabled;
}

public static void setEnabled(TFMPageID _page, Name _AIName, int _AI, NoYes _value)
{
    TFMGS1AITypeBarcodeSetup    typeBarcodeValue;
    TFMGS1AISetup               setup;

    select firstonly RecId from setup where setup.Name == _AIName && setup.GS1AI == _AI;
    if (!setup.RecId)
    {
        return;
    }
    ttsbegin;   
    select firstonly forupdate typeBarcodeValue where typeBarcodeValue.PageID == _page && typeBarcodeValue.TFMGS1AITableRef == setup.RecId;

    typeBarcodeValue.PageID = _page;
    typeBarcodeValue.TFMGS1AITableRef = setup.RecId;
    typeBarcodeValue.Enabled = _value;
    typeBarcodeValue.write();

    ttscommit;

    TFMPagesProvider::updateVersion();
}

public static void modifyOutput(XmlElement _typeBarcodeElement, TFMPageID _pageId)
{
    XmlElement  qualifiers = _typeBarcodeElement.ownerDocument().createElement('qualifiers');
    XmlElement  qualifier;
    TFMGS1AITypeBarcodeSetup pageAISetup;
    TFMGS1AISetup           AISetup;

    while select pageAISetup where pageAISetup.PageID == _pageId
        join AISetup where AISetup.RecId == pageAISetup.TFMGS1AITableRef
    {
        qualifier = _typeBarcodeElement.ownerDocument().createElement('qualifier');
        qualifier.setAttribute('ai',strRFix(int2Str(AISetup.GS1AI), 2, '0'));
        qualifier.setAttribute('displayValue', AISetup.Name + ' ('+strRFix(int2Str(AISetup.GS1AI), 2, '0')+')');
        qualifiers.appendChild(qualifier);
    }
    if (qualifier != null)
    {
        //qualifier added, add qualifiers node
        _typeBarcodeElement.appendChild(qualifiers);
    }
}
